task.vi:
Cho khai báo:
    union {
        unsigned x;
        unsigned char y[2];
    } z = {0xabcd};
Chọn câu đúng nhất trong các câu sau:
A: Khai báo trên là sai vì thiếu tên kiểu
B: Khởi tạo biến z là sai vì chỉ có một giá trị (0xabcd)
C: z.y[0] = 0xab
D: z.y[1] = 0xab

task.en:
Given the declaration:
    union {
        unsigned x;
        unsigned char y[2];
    } z = {0xabcd};
Select the most correct statement among the following:
A: The declaration above is invalid because it lacks a type name
B: Initializing variable z is invalid because there is only one value (0xabcd)
C: z.y[0] = 0xab
D: z.y[1] = 0xab

example.code:
#include <iostream>
#include <cstdint>

// Giao thoa bo nho giua 1 so 16-bit va mang 2 bytes
union ByteViewer {
    std::uint16_t value;
    std::uint8_t bytes[2];
};

int main() {
    ByteViewer bv;
    bv.value = 0xABCD;

    // In ra gia tri hex cua tung byte de quan sat kien truc Little-Endian
    std::cout << "Value: 0x" << std::hex << bv.value << std::endl;
    std::cout << "Byte 0: 0x" << static_cast<int>(bv.bytes[0]) << std::endl;
    std::cout << "Byte 1: 0x" << static_cast<int>(bv.bytes[1]) << std::endl;

    return 0;
}

#include <iostream>

enum Bool {
    FalseVal = 0,
    TrueVal = 1
};

enum Direction {
    North = 0,
    East,
    South,
    West
};

int main() {
    Bool ok = TrueVal;
    std::cout << "ok value: " << ok << std::endl;

    // Ep kieu tuong minh tu so nguyen sang enum
    int rawCode = 2;
    Direction dir = static_cast<Direction>(rawCode); // Hoac Direction(rawCode)

    std::cout << "Direction code: " << dir << std::endl;
    if (dir == South) {
        std::cout << "Facing South" << std::endl;
    }

    return 0;
}
